# -*- coding: utf-8 -*-
from cuerpo import plan, objetivos

_RUTAS = [
    (("creat", "imagen", "copia", "copy", "video", "diseno", "banner"), "creatividad"),
    (("anuncio", "ads", "campana", "pauta", "presupuesto de ads"), "publicidad"),
    (("experimento", "ab test", "hipotesis", "test"), "experimental"),
    (("dato", "kpi", "analisis", "metric", "forecast", "clic", "costo", "cuanto",
      "resultado", "venta", "gasto", "retorno"), "datos"),
    (("web", "landing", "pagina", "seo", "ux"), "desarrollo"),
    (("precio", "competencia", "mercado", "tendencia"), "mercado"),
    (("publicar", "subir", "post"), "publicacion"),
]
_DEPARTAMENTO_DEFECTO = "gobierno"


def _contiene(tarea, claves):
    t = (tarea or "").lower()
    return any(k in t for k in claves)


def departamento(tarea):
    for claves, depto in _RUTAS:
        if _contiene(tarea, claves):
            return depto
    return _DEPARTAMENTO_DEFECTO


def coordinar(empresa, formato):
    return {"permitido": plan.hay_combustible(empresa, formato)}


_DEFECTO_APROBACION = {"videos": True, "imagenes": True, "texto": False}


def requiere_aprobacion(formato, reglas=None):
    reglas = reglas or _DEFECTO_APROBACION
    t = (formato or "").lower()
    if "texto" in t or "copy" in t:
        tipo = "texto"
    elif "video" in t:
        tipo = "videos"
    else:
        tipo = "imagenes"
    return reglas.get(tipo, _DEFECTO_APROBACION[tipo])


def meta_actual(empresa):
    objetivos.cargar(empresa)
    arbol = objetivos.arbol()
    return (arbol.get("raiz") or {}).get("nombre") or "ventas"


usa_presupuesto_de = "plan"
usa_aprobacion_de = "aprobacion"
usa_objetivos_de = "objetivos"
